SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."id" AS "id", "_root.base"."title" AS "title", "_root.or.author"."author" AS "author"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."article"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST LIMIT 50000 ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.or.author.base"."name" AS "name"       ) AS "_e"      ) ) AS "author" FROM  (SELECT  *  FROM "public"."author"  WHERE (("_root.base"."author_id") = ("id"))    LIMIT 1 ) AS "_root.or.author.base"      ) AS "_root.or.author" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"      
